document.body.insertAdjacentHTML('beforeend',`<aside class="search-overlay" aria-hidden="true"><div class="search-shell"><div class="search-top"><strong>Search all FinMark Trust content</strong><button class="close-search" aria-label="Close search">×</button></div><form class="global-input"><input id="global-search" type="search" placeholder="Search data, research and programmes" autocomplete="off"><button type="submit">Search</button></form><p class="search-hint">Try “FinScope South Africa”, “women” or “remittances”</p><div class="search-results" aria-live="polite"></div></div></aside>`);
const overlay=document.querySelector('.search-overlay'), globalInput=document.querySelector('#global-search'), results=document.querySelector('.search-results');
function renderResults(q=''){const query=q.trim().toLowerCase();const items=query?searchData.filter(i=>(i.title+' '+i.type+' '+i.meta).toLowerCase().includes(query)):searchData.slice(0,5);results.innerHTML=items.length?items.map(i=>`<a class="search-result" href="${i.url}"><small>${i.type}</small><strong>${i.title}</strong><span>${i.meta}</span></a>`).join(''):`<div class="no-results">No results yet. Try a broader topic, country or content type.</div>`}
function openSearch(){overlay.classList.add('open');overlay.setAttribute('aria-hidden','false');document.body.classList.add('lock');renderResults();setTimeout(()=>globalInput.focus(),20)}function closeSearch(){overlay.classList.remove('open');overlay.setAttribute('aria-hidden','true');document.body.classList.remove('lock')}
document.querySelectorAll('.open-search').forEach(b=>b.addEventListener('click',openSearch));document.querySelector('.close-search').addEventListener('click',closeSearch);globalInput.addEventListener('input',e=>renderResults(e.target.value));document.querySelector('.global-input').addEventListener('submit',e=>e.preventDefault());document.addEventListener('keydown',e=>{if(e.key==='Escape')closeSearch();if(e.key==='/'&&!/INPUT|TEXTAREA/.test(document.activeElement.tagName)){e.preventDefault();openSearch()}});
const menu=document.querySelector('.menu-btn'), panel=document.querySelector('.mobile-panel');menu.addEventListener('click',()=>{const on=panel.classList.toggle('open');menu.setAttribute('aria-expanded',on)});
